    Direction curDirection = controller.getInputDirection();
    bool hasFood = snake.move(curDirection, gameMap);
    bool die = not snake.chkAlive(gameMap);  
    if (die) {
      return 0;
    }

    if (hasFood) {
      gameMap.spawnFood(snake);
    }

    Sleep(200); 
